// @ts-check
/* ============================================================================
 * proof.js | Proof of achievement on the homepage
 * ----------------------------------------------------------------------------
 * Reads data/proof-manifest.json - the same file the Rank 2 Blueprint uses,
 * generated by scripts/proof_documents.py from whatever sits in assets/proof/.
 * Drop a scan (PDF/JPG/PNG/WEBP) into assets/proof/, run `npm run publish`,
 * and a card appears here and on the blueprint. No list to keep in sync.
 *
 * Image documents open in the lightbox; PDFs open in a new tab. If the
 * manifest has no documents the section keeps its `hidden` attribute and the
 * page claims nothing.
 *
 * `window.HOA.proof` resolves to the list that was shown.
 * ========================================================================== */
(async () => {
  "use strict";
  const { esc } = HOA;

  /** @type {(value: any[]) => void} */
  let settle = () => {};
  HOA.proof = new Promise((r) => (settle = r));

  const proofSection = document.getElementById("proofSection");
  const proofGrid = document.getElementById("proofGrid");
  const proofLb = document.getElementById("proofLightbox");
  if (!proofSection || !proofGrid || !proofLb) return settle([]);

  /** @type {any} */
  let manifest = null;
  try {
    const r = await fetch("data/proof-manifest.json");
    if (r.ok) manifest = await r.json();
  } catch (_) { /* offline or missing: show nothing */ }

  /* One card per slot. When two files claim the same slot (e.g. a re-saved
     copy of the result card), keep the one metadata.json describes. */
  /** @type {Map<string, any>} */
  const bySlot = new Map();
  for (const s of (manifest && manifest.slots) || []) {
    if (!s || !s.doc || !s.doc.file) continue;
    const key = String(s.slot || s.id);
    const prev = bySlot.get(key);
    if (!prev || (!prev.doc.title && s.doc.title)) bySlot.set(key, s);
  }
  const found = [...bySlot.values()]
    .map((/** @type {any} */ s) => ({
      file: String(s.doc.file),
      kind: s.doc.kind === "pdf" ? "pdf" : "image",
      type: String(s.doc.type || ""),
      size: String(s.doc.size || ""),
      title: String(s.doc.title || s.label || "Document"),
      note: String(s.doc.note || ""),
    }));
  settle(found);
  if (!found.length) return;

  proofGrid.innerHTML = found
    .map((it) => {
      const meta = `<span class="proof-badge">${esc(it.type)}${it.size ? " · " + esc(it.size) : ""}</span>`;
      const text = `<h3>${esc(it.title)}</h3>${it.note ? `<p>${esc(it.note)}</p>` : ""}`;
      if (it.kind === "pdf") {
        return `
    <a class="proof-card" href="${esc(it.file)}" target="_blank" rel="noopener">
      <span class="proof-thumb proof-thumb-pdf" aria-hidden="true">
        <span class="proof-pdf-icon">PDF</span>
        <span class="proof-zoom">Open document</span>
      </span>
      ${text}${meta}
    </a>`;
      }
      return `
    <button class="proof-card" type="button"
            data-src="${esc(it.file)}" data-title="${esc(it.title)}"
            data-note="${esc(it.note)}">
      <span class="proof-thumb">
        <img src="${esc(it.file)}" alt="${esc(it.title)}" width="800" height="600" loading="lazy" decoding="async">
        <span class="proof-zoom">Click to enlarge</span>
      </span>
      ${text}${meta}
    </button>`;
    })
    .join("");
  proofSection.hidden = false;

  /* getElementById types these as HTMLElement; the lightbox's image needs the
     HTMLImageElement surface (src, alt, naturalWidth), so narrow it here
     rather than sprinkling casts through the handler below. */
  const lbImg = /** @type {HTMLImageElement | null} */ (
    document.getElementById("proofLbImg")
  );
  const lbCap = document.getElementById("proofLbCap");
  const lbClose = document.getElementById("proofClose");
  const closeLb = () => {
    proofLb.hidden = true;
    document.documentElement.style.overflow = "";
  };

  proofGrid.addEventListener("click", (e) => {
    const card = /** @type {HTMLElement | null} */ (
      /** @type {Element} */ (e.target).closest("button.proof-card")
    );
    if (!card || !lbImg || !lbCap) return;
    lbImg.src = card.dataset.src || "";
    lbImg.alt = card.dataset.title || "";
    /* The HTML width/height are a placeholder ratio; correct them to the real
       ones so object-fit never letterboxes a portrait scan. */
    const sync = () => {
      if (lbImg.naturalWidth) {
        lbImg.width = lbImg.naturalWidth;
        lbImg.height = lbImg.naturalHeight;
      }
    };
    if (lbImg.complete) sync();
    else lbImg.addEventListener("load", sync, { once: true });
    lbCap.textContent = card.dataset.note
      ? `${card.dataset.title} — ${card.dataset.note}`
      : card.dataset.title || "";
    proofLb.hidden = false;
    document.documentElement.style.overflow = "hidden";
    lbClose?.focus();
  });
  lbClose?.addEventListener("click", closeLb);
  /* Click the backdrop (not the figure) or Escape to dismiss. */
  proofLb.addEventListener("click", (e) => {
    if (e.target === proofLb) closeLb();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !proofLb.hidden) closeLb();
  });
})();
